steps.script:
GameState.state["factions"]["1"].merge({"detachment": "Taktikal Brigade"}, true)
StratagemManager.load_faction_stratagems_for_player(1)
var u = GameState.state.units
var ko: Array = u["U_KOMMANDOS_A"].models
for i in range(ko.size()):
	var t := float(i) / float(ko.size() - 1)
	ko[i]["position"] = {"x": lerpf(11.0, 20.8, t) * 40.0, "y": lerpf(22.8, 29.2, t) * 40.0}
for uid in ["U_BOYZ_B", "U_WARBOSS_A"]:
	for m in u[uid].models:
		m["position"] = {"x": float(m.position.x), "y": float(m.position.y) - 320.0}
var i := 0
for m in u["U_CUSTODIAN_GUARD_A"].models:
	m["position"] = {"x": 1040.0 + i * 72.0, "y": 1760.0}
	i += 1
i = 0
for m in u["U_PROSECUTORS_A"].models:
	m["position"] = {"x": 1080.0 + i * 56.0, "y": 2000.0}
	i += 1
tree.current_scene._recreate_unit_visuals()
MissionManager.check_all_objectives()
return "%s|%s" % [str(MissionManager.objective_control_state.get("obj_nml_1", 0)), str(MissionManager.objective_control_state.get("obj_center", 0))]

var ko: Array = GameState.state.units["U_KOMMANDOS_A"].models
for i in range(ko.size()):
	ko[i]["position"] = {"x": 760.0 + i * 52.0, "y": 640.0}
tree.current_scene._recreate_unit_visuals()
MissionManager.check_all_objectives()
return "%s|%s" % [str(MissionManager.objective_control_state.get("obj_nml_1", 0)), str(MissionManager.objective_control_state.get("obj_center", 0))]
